        public Result UpdateDoubleComm(int userId, int custId, bool isDoubleComm)
        {
            try
            {
                using (ObjectDb db = new ObjectDb("Acc_CustomerUpdDoubleCommLosing"))
                {
                    db.AddInParameter("userid", DbType.Int32, userId);
                    db.AddInParameter("custid", DbType.Int32, custId);
                    db.AddInParameter("doublecommlosing", DbType.Boolean, CastAide.AsBoolean(isDoubleComm));
                    db.AddInParameter("ip", DbType.String, System.Web.HttpContext.Current.Request.UserHostAddress);

                    db.AddOutParameter("errmsg", DbType.String, 500);
                    db.AddOutParameter("errcode", DbType.Int32, sizeof(int));

                    db.ExecuteNonQuery();

                    var errMsg = DNAide.Core.CastAide.AsString(db.GetParameterValue("ErrMsg"));
                    var errCode = DNAide.Core.CastAide.AsInt32(db.GetParameterValue("errcode"));
                    return new Result { ErrorCode = errCode, ErrorMessage = errMsg };
                }
            }
            catch (Exception e)
            {
                return new Result { ErrorCode = 1, ErrorMessage = e.Message };
            }
        }

